// The CLI-agnostic Cloudflare CLI auth layer.
//
// This is the auth machinery that previously lived, wrangler-specific, in
// `packages/wrangler/src/user/user.ts`: OAuth flow wiring (with the CLI's
// branded consent pages / keyring service name / credential storage), login /
// logout / refresh, credential resolution, account selection, and the
// `requireAuth` / `requireApiToken` entry points.
//
// Everything that varies between CLIs (wrangler, cf, …) is read from the
// injected {@link CliDescriptor} descriptor — config paths, file format, client
// id, consent pages, redirect URI, keyring service name, CLI name, and copy —
// so a new CLI is a descriptor rather than a fork of this factory. The only
// genuine consumer primitives (logger, interactive `prompt` / `select`, and the
// User-Agent string) come in via {@link AuthContext}.

import { URLSearchParams } from "node:url";
import {
	createConfigCache,
	fetchInternalBase,
	getCloudflareComplianceRegion,
	hasMorePages,
	isCI,
	isNonInteractiveOrCI,
	openInBrowser,
	throwFetchError,
	UserError,
} from "@cloudflare/workers-utils";
import { formatDistanceToNowStrict } from "date-fns";
import { dedent } from "ts-dedent";
import { validateAccountId } from "../account-id";
import { createCredentialStorageContext } from "../credential-store";
import { getAuthFromEnv } from "../credentials";
import { getCloudflareAccountIdFromEnv as getAccountIdFromEnv } from "../env-vars";
import { createOAuthFlow } from "../flow";
import { createFileStorage } from "./file-storage";
import { createPreferences } from "./preferences";
import { createTemporaryTermsPrompt } from "./temporary-terms";
import type { UserAuthConfig } from "../config-file/auth";
import type { TemporaryPreviewAccount } from "../config-file/temporary";
import type {
	TemporaryAccountLogger,
	TemporaryAccountRequest,
} from "../context";
import type { CredentialStore } from "../credential-store";
import type {
	LoginOrRefreshFailureReason,
	LoginOrRefreshResult,
	LoginProps,
} from "../flow";
import type { AuthContext, CliDescriptor } from "./types";
import type {
	ApiCredentials,
	ComplianceConfig,
	FetchResult,
} from "@cloudflare/workers-utils";

/** Details for one of the user's accounts. */
export type Account = { id: string; name: string };

/** The config surface {@link CloudflareAuth.requireAuth} needs: compliance settings plus an optional `account_id`. */
export type RequireAuthConfig = ComplianceConfig & { account_id?: string };

/** Overrides accepted by {@link CloudflareAuth.login} / {@link CloudflareAuth.loginOrRefreshIfRequired}. */
export interface CloudflareLoginProps {
	scopes?: string[];
	browser?: boolean;
	callbackHost?: string;
	callbackPort?: number;
	profile?: string;
	/**
	 * When `true`, authenticate using the OAuth 2.0 Device Authorization Grant
	 * (RFC 8628) instead of the authorization-code-with-PKCE callback flow. The
	 * device flow does not start a local callback server, so `callbackHost` and
	 * `callbackPort` are ignored when this is set.
	 */
	device?: boolean;
}

/** A Cloudflare CLI's auth layer, returned by {@link createCloudflareAuth}. */
export interface CloudflareAuth {
	/** Set the active auth profile for all subsequent credential lookups. */
	setProfile: (profile: string) => void;
	/** Return the active auth profile name. */
	getActiveProfile: () => string;
	/** The currently-active credential store for the active profile. */
	getCredentialStore: () => CredentialStore;
	/** Mark whether `--temporary` is permitted for the current invocation. */
	setTemporaryAllowed: (
		allowed: boolean,
		request?: TemporaryAccountRequest
	) => void;

	/** Resolve API credentials (env / temporary account / stored OAuth token). */
	getAPIToken: () => ApiCredentials | undefined;
	/** Throw an error if there is no API token available. */
	requireApiToken: () => ApiCredentials;

	/** Open the browser, complete the OAuth login, and persist the token. */
	login: (
		complianceConfig: ComplianceConfig,
		props?: CloudflareLoginProps
	) => Promise<boolean>;
	/** Revoke and delete the stored OAuth token. */
	logout: (profile?: string) => Promise<void>;
	/** Ensure the user is authenticated, refreshing or prompting as needed. */
	loginOrRefreshIfRequired: (
		complianceConfig: ComplianceConfig,
		props?: CloudflareLoginProps
	) => Promise<LoginOrRefreshResult>;
	/** Read the OAuth access token from local state, refreshing first if needed. */
	getOAuthTokenFromLocalState: () => Promise<string | undefined>;
	/** Scopes granted to the stored OAuth token, or `undefined` when not OAuth-logged-in. */
	getScopes: () => string[] | undefined;

	/** Read stored OAuth credentials via the active credential store. */
	readAuthCredentials: () => UserAuthConfig | undefined;
	/** Persist OAuth credentials via the active credential store. */
	writeAuthCredentials: (config: UserAuthConfig) => void;

	/** Returns the active account ID without side effects (config → env → cache). */
	getActiveAccountId: (config: { account_id?: string }) => string | undefined;
	/** Resolve the account ID to use for API requests (fetching / prompting if needed). */
	getOrSelectAccountId: (config: RequireAuthConfig) => Promise<string>;
	/** Retrieve the cached account for the active profile, if any. */
	getAccountFromCache: () => Account | undefined;
	/** Fetch the accounts the current login auth can actually use. */
	fetchAllAccounts: (
		complianceConfig: ComplianceConfig,
		options?: { throwOnEmpty?: boolean }
	) => Promise<Account[]>;

	/** Ensure the user is logged in and resolve a valid account ID. */
	requireAuth: (config: RequireAuthConfig) => Promise<string>;
}

// Cloudflare API error codes returned by `/memberships` that mean "the current
// auth cannot read memberships".
//   - 9106 ("Authentication failed"): what `/memberships` returns for Account
//     API Tokens. `/memberships` is a user-level endpoint and account-scoped
//     tokens have no user identity, so the API rejects them at this endpoint
//     even though a valid Bearer token was sent.
//   - 10000 (Authentication error): the token is not accepted by the
//     `/memberships` endpoint, but `/accounts` may still work for the same auth
//     (e.g. tokens missing the membership read scope).
const MEMBERSHIPS_INACCESSIBLE_CODES = [9106, 10000];

function getErrorCode(err: unknown): number | undefined {
	return (err as { code?: number } | undefined)?.code;
}

function isMembershipsInaccessible(err: unknown): boolean {
	const code = getErrorCode(err);
	return code !== undefined && MEMBERSHIPS_INACCESSIBLE_CODES.includes(code);
}

// Maps a `loginOrRefreshIfRequired` failure reason to the user-facing body of
// the "Not logged in" error thrown before the account/membership REST calls.
function notLoggedInErrorBodies(
	loginCommand: string
): Record<LoginOrRefreshFailureReason, string> {
	return {
		"no-credentials-non-interactive": `Could not authenticate because no credentials were found and the environment is non-interactive. Set a CLOUDFLARE_API_TOKEN environment variable or run \`${loginCommand}\` in an interactive terminal first.`,
		"no-credentials-login-failed": `No credentials were found and the login attempt was unsuccessful. Run \`${loginCommand}\` to try again.`,
		"token-expired-non-interactive": `Your auth token has expired and could not be refreshed, and the environment is non-interactive. Run \`${loginCommand}\` in an interactive terminal or set a CLOUDFLARE_API_TOKEN.`,
		"token-expired-login-failed": `Your auth token has expired and could not be refreshed, and the login attempt was unsuccessful. Run \`${loginCommand}\` to try again.`,
		"token-refresh-unreachable": `Your auth token has expired and could not be refreshed because the Cloudflare auth server could not be reached. This is usually a network problem (connectivity, proxy, or IPv6), not an invalid login: your stored credentials were left unchanged. Check your connection and try again.`,
	};
}

function logTemporaryPreviewAccount(
	temporaryAccountLogger: TemporaryAccountLogger,
	temporaryPreviewAccount: TemporaryPreviewAccount,
	cached: boolean
): void {
	const claimExpiresAt = new Date(temporaryPreviewAccount.claim.expiresAt);
	temporaryAccountLogger.log(
		dedent`
			Temporary account ready:
				Account: ${temporaryPreviewAccount.account.name} (${cached ? "reused" : "created"})
				Claim within: ${formatDistanceToNowStrict(claimExpiresAt)}
				Claim URL: ${temporaryPreviewAccount.claim.url}
		`
	);
}

/**
 * Build a Cloudflare CLI's auth layer ({@link CloudflareAuth}) for the given
 * CLI descriptor and context.
 *
 * Creates the credential-storage bundle and the single OAuth flow instance
 * internally, then returns every high-level helper the CLI's commands use.
 */
export function createCloudflareAuth(
	descriptor: CliDescriptor,
	ctx: AuthContext
): CloudflareAuth {
	const { logger } = ctx;
	const temporaryAccountLogger = ctx.temporaryAccountLogger ?? logger;
	const cliName = descriptor.cliName;
	const NOT_LOGGED_IN_ERROR_BODIES = notLoggedInErrorBodies(
		descriptor.commands.login
	);
	const NOT_LOGGED_IN_WHOAMI_TIP = `\nRun \`${descriptor.commands.whoami}\` to check your current authentication status.`;

	const preferences = createPreferences(descriptor.getConfigPath);

	// The config cache is generic file-backed storage owned by
	// `@cloudflare/workers-utils`; build our own instance bound to the injected
	// logger. The namespace isolates each CLI's cache dir so one CLI's
	// login/logout purge (`purgeConfigCaches`) never deletes another's.
	const configCache = createConfigCache(
		logger,
		descriptor.cacheNamespace
			? { namespace: descriptor.cacheNamespace }
			: undefined
	);

	// The CLI's credential-storage bundle. Plumbs the user-level keyring
	// opt-in preference into the storage resolver so the OAuth flow's
	// reads/writes go through whichever store (plaintext or
	// encrypted-file-with-keyring-key) the user has chosen. Each resolved store
	// re-resolves the active backend per call, so both profile switches and
	// runtime preference flips take effect immediately.
	const credentialStorage = createCredentialStorageContext({
		serviceName: descriptor.keyringServiceName,
		getConfigPath: descriptor.getConfigPath,
		isKeyringEnabled: () =>
			preferences.readUserPreferences().keyring_enabled === true,
		logger,
		isNonInteractiveOrCI,
		loginCommand: descriptor.commands.login,
		format: descriptor.fileFormat,
	});

	// The single CLI-wide OAuth flow instance. `generateAuthUrl` /
	// `generateRandomState` are left to the flow's own defaults (from the shared
	// core); tests keep deterministic snapshot URLs by normalising the random
	// `state` / `code_challenge` values rather than mocking these.
	// Resolved once so the env-credential *presence* check and the env-credential
	// *resolution* agree. Otherwise a CLI that disables the global API key
	// (e.g. cf) would still treat a bare `CLOUDFLARE_API_KEY`/`CLOUDFLARE_EMAIL`
	// pair as "logged in via env" and block login/logout, even though its token
	// resolution ignores those creds.
	const allowGlobalAuthKey = descriptor.allowGlobalAuthKey ?? true;

	const oauthFlow = createOAuthFlow({
		logger,
		isNonInteractiveOrCI,
		openInBrowser: (url) => openInBrowser(url, logger),
		hasEnvCredentials: () =>
			getAuthFromEnv({ allowGlobalAuthKey }) !== undefined,
		purgeOnLoginOrLogout: configCache.purgeConfigCaches,
		clientId: descriptor.clientId,
		consent: descriptor.consent,
		displayName: descriptor.displayName,
		deviceLoginCommand: descriptor.commands.deviceLogin,
		redirectUri: descriptor.redirectUri,
		storageFactory: credentialStorage.storageFactory,
		allowGlobalAuthKey,
		temporary: {
			// The temporary-preview-account cache is CLI-owned storage (a
			// file under the global config dir, scoped to the Cloudflare API
			// environment), so it's built here rather than injected.
			storage: createFileStorage<TemporaryPreviewAccount>(
				descriptor.fileFormat,
				descriptor.getTemporaryAccountConfigPath
			),
			prompt: createTemporaryTermsPrompt({
				temporaryAccountLogger,
				prompt: ctx.prompt,
			}),
			temporaryAccountLogger,
		},
	});

	function setProfile(profile: string): void {
		oauthFlow.setProfile(profile);
	}

	function getActiveProfile(): string {
		return oauthFlow.getActiveProfile();
	}

	function getCredentialStore(): CredentialStore {
		return credentialStorage.getActiveStore(oauthFlow.getActiveProfile());
	}

	function setTemporaryAllowed(
		allowed: boolean,
		request?: TemporaryAccountRequest
	): void {
		oauthFlow.setTemporaryAllowed(allowed, request);
	}

	function getAPIToken(): ApiCredentials | undefined {
		return oauthFlow.getAPIToken();
	}

	function requireApiToken(): ApiCredentials {
		return oauthFlow.requireApiToken();
	}

	function withLoginDefaults(
		complianceConfig: ComplianceConfig,
		props: CloudflareLoginProps | undefined
	): LoginProps {
		return {
			complianceConfig,
			scopes: props?.scopes ?? descriptor.getDefaultScopeKeys(),
			browser: props?.browser ?? true,
			callbackHost: props?.callbackHost,
			callbackPort: props?.callbackPort,
			profile: props?.profile,
			device: props?.device ?? descriptor.useDeviceFlowByDefault ?? false,
		};
	}

	async function login(
		complianceConfig: ComplianceConfig,
		props?: CloudflareLoginProps
	): Promise<boolean> {
		return oauthFlow.login(withLoginDefaults(complianceConfig, props));
	}

	async function logout(profile?: string): Promise<void> {
		return oauthFlow.logout(profile);
	}

	async function loginOrRefreshIfRequired(
		complianceConfig: ComplianceConfig,
		props?: CloudflareLoginProps
	): Promise<LoginOrRefreshResult> {
		if (oauthFlow.getActiveTemporaryAccount()) {
			return { loggedIn: true };
		}

		return oauthFlow.loginOrRefreshIfRequired(
			withLoginDefaults(complianceConfig, props)
		);
	}

	async function getOAuthTokenFromLocalState(): Promise<string | undefined> {
		return oauthFlow.getOAuthTokenFromLocalState();
	}

	function getScopes(): string[] | undefined {
		return oauthFlow.getScopes();
	}

	function readAuthCredentials(): UserAuthConfig | undefined {
		return credentialStorage.storageFactory(getActiveProfile()).read();
	}

	function writeAuthCredentials(config: UserAuthConfig): void {
		credentialStorage.storageFactory(getActiveProfile()).write(config);
	}

	function getAccountCacheFileName(): string {
		const profile = oauthFlow.getActiveProfile();
		if (profile === "default") {
			return `${descriptor.accountCachePrefix}.json`;
		}
		return `${descriptor.accountCachePrefix}-${profile}.json`;
	}

	function saveAccountToCache(account: Account): void {
		configCache.saveToConfigCache<{ account: Account }>(
			getAccountCacheFileName(),
			{ account }
		);
	}

	function getAccountFromCache(): Account | undefined {
		return configCache.getConfigCache<{ account: Account }>(
			getAccountCacheFileName()
		).account;
	}

	// Fetch every page of a paginated Cloudflare REST list resource. Authentication
	// is resolved once by `fetchAllAccounts` before its account and membership
	// requests fan out, so both requests share the same credentials without
	// starting concurrent login flows.
	async function fetchAccountsPaged<ResponseType>(
		complianceConfig: ComplianceConfig,
		resource: string,
		credentials: ApiCredentials
	): Promise<ResponseType[]> {
		const results: ResponseType[] = [];
		let getMoreResults = true;
		let page = 1;
		let queryParams: URLSearchParams | undefined;
		while (getMoreResults) {
			queryParams = new URLSearchParams(queryParams);
			queryParams.set("page", String(page));

			const { response: json, status } = await fetchInternalBase<
				FetchResult<ResponseType[]>
			>(
				complianceConfig,
				resource,
				{},
				ctx.userAgent,
				logger,
				queryParams,
				undefined,
				credentials
			);
			if (json.success) {
				results.push(...json.result);
				if (hasMorePages(json.result_info)) {
					page = page + 1;
				} else {
					getMoreResults = false;
				}
			} else {
				throwFetchError(resource, json, status);
			}
		}
		return results;
	}

	async function fetchAllAccounts(
		complianceConfig: ComplianceConfig,
		options: { throwOnEmpty?: boolean } = {}
	): Promise<Account[]> {
		const { throwOnEmpty = true } = options;
		const loginResult = await loginOrRefreshIfRequired(complianceConfig);
		if (!loginResult.loggedIn) {
			throw new UserError(
				`Not logged in. ${NOT_LOGGED_IN_ERROR_BODIES[loginResult.reason]}${NOT_LOGGED_IN_WHOAMI_TIP}`,
				{ telemetryMessage: "cfetch auth login required" }
			);
		}
		const credentials = requireApiToken();

		const [accountsRes, membershipsRes] = await Promise.allSettled([
			fetchAccountsPaged<Account>(complianceConfig, `/accounts`, credentials),
			fetchAccountsPaged<{ account: Account }>(
				complianceConfig,
				`/memberships`,
				credentials
			),
		]);

		if (accountsRes.status === "rejected") {
			throw accountsRes.reason;
		}

		if (membershipsRes.status === "rejected") {
			if (isMembershipsInaccessible(membershipsRes.reason)) {
				if (
					accountsRes.status === "fulfilled" &&
					accountsRes.value.length > 0
				) {
					// Fall back to `/accounts`, which is already scoped to what the auth can use.
					return accountsRes.value;
				}
				// 9106 specifically can be returned when an environment variable like
				// CLOUDFLARE_API_TOKEN is set to an invalid value — surface that hint.
				const errCode = getErrorCode(membershipsRes.reason);
				if (errCode === 9106) {
					throw new UserError(
						`Failed to automatically retrieve account IDs for the logged in user.
You may have incorrect permissions on your API token, or an environment variable such as CLOUDFLARE_API_TOKEN, CLOUDFLARE_API_KEY, or CLOUDFLARE_EMAIL may be set to an invalid value.
Check your environment and unset or correct any Cloudflare credential variables, or run \`${descriptor.commands.login}\` to re-authenticate.
You can also skip this account check by adding an \`account_id\` in your ${descriptor.getConfigFileLabel()} file, or by setting the value of CLOUDFLARE_ACCOUNT_ID`,
						{ telemetryMessage: "user account fetch permission denied" }
					);
				}
				throw new UserError(
					`Failed to automatically retrieve account IDs for the logged in user.
You may have incorrect permissions on your API token, or your authentication may have expired. Try running \`${descriptor.commands.login}\` to re-authenticate. You can also skip this account check by adding an \`account_id\` in your ${descriptor.getConfigFileLabel()} file, or by setting the value of CLOUDFLARE_ACCOUNT_ID`,
					{ telemetryMessage: "user account fetch permission denied" }
				);
			} else {
				throw membershipsRes.reason;
			}
		}

		const membershipIds = new Set(
			membershipsRes.value.map((m) => m.account.id)
		);
		const usableAccounts = accountsRes.value.filter((a) =>
			membershipIds.has(a.id)
		);

		if (usableAccounts.length === 0 && throwOnEmpty) {
			throw new UserError(
				`Failed to automatically retrieve account IDs for the logged in user.
In a non-interactive environment, it is mandatory to specify an account ID, either by assigning its value to CLOUDFLARE_ACCOUNT_ID, or as \`account_id\` in your ${descriptor.getConfigFileLabel()} file.
Alternatively, try running \`${descriptor.commands.login}\` to re-authenticate.`,
				{ telemetryMessage: "user account fetch empty" }
			);
		}

		return usableAccounts;
	}

	function getActiveAccountId(config: {
		account_id?: string;
	}): string | undefined {
		// When operating as a temporary preview account, its id is the whole
		// identity and takes precedence over config/env/cache.
		const temporaryAccount = oauthFlow.getActiveTemporaryAccount();
		if (temporaryAccount) {
			return temporaryAccount.account.id;
		}

		if (config.account_id) {
			return validateAccountId(
				config.account_id,
				`set as \`account_id\` in your ${descriptor.getConfigFileLabel()} file`
			);
		}
		const envAccountId = getAccountIdFromEnv();
		if (envAccountId) {
			return envAccountId;
		}
		return getAccountFromCache()?.id;
	}

	async function getOrSelectAccountId(
		config: RequireAuthConfig
	): Promise<string> {
		// TODO: v5 we should prioritise the env var instead of the config value here,
		// for consistency with other env vars.
		const activeAccountId = getActiveAccountId(config);
		if (activeAccountId) {
			return activeAccountId;
		}

		const accounts = await fetchAllAccounts(config);
		if (accounts.length === 1) {
			saveAccountToCache({ id: accounts[0].id, name: accounts[0].name });
			return accounts[0].id;
		}

		try {
			const accountID = await ctx.select("Select an account", {
				choices: accounts.map((account) => ({
					title: account.name,
					value: account.id,
				})),
			});
			const account = accounts.find((a) => a.id === accountID);
			if (!account) {
				throw new Error("Selected account not found in accounts list");
			}
			saveAccountToCache({ id: account.id, name: account.name });
			return accountID;
		} catch (e) {
			// Did we try to select an account in CI or a non-interactive terminal?
			if (ctx.isNoDefaultValueProvidedError(e)) {
				// Redact account names (which may contain email addresses) in CI
				// to avoid leaking sensitive information in public CI logs.
				// Non-interactive terminals (agents, piped commands) still need
				// to see account names to identify which account to configure.
				const redactAccountName = isCI();
				throw new UserError(
					`More than one account available but unable to select one in non-interactive mode.
Please set the appropriate \`account_id\` in your ${descriptor.getConfigFileLabel()} file or assign it to the \`CLOUDFLARE_ACCOUNT_ID\` environment variable.
Available accounts are (\`<name>\`: \`<account_id>\`):
${accounts
	.map(
		(account: Account) =>
			`  \`${redactAccountName ? "(redacted)" : account.name}\`: \`${
				account.id
			}\``
	)
	.join("\n")}`,
					{ telemetryMessage: "user account selection unavailable" }
				);
			}
			throw e;
		}
	}

	async function requireAuth(config: RequireAuthConfig): Promise<string> {
		if (oauthFlow.isTemporaryAllowed()) {
			if (getCloudflareComplianceRegion(config) !== "public") {
				throw new UserError(
					"Temporary accounts aren't available when the compliance region is not set to public.",
					{
						telemetryMessage:
							"user temporary account unavailable in compliance region",
					}
				);
			}

			// This command run made this temporary account. It is not an earlier
			// login, so use it again. Some commands call `requireAuth` more than
			// one time, for example `d1 migrations apply --remote`. Without this
			// check, the second call fails at the test below.
			const latchedTemporaryAccount = oauthFlow.getActiveTemporaryAccount();
			if (latchedTemporaryAccount) {
				return latchedTemporaryAccount.account.id;
			}

			// `--temporary` is only for unauthenticated use. If any credentials are
			// already available (env, global key, or a stored OAuth token), refuse
			// rather than silently provisioning a throwaway account alongside them.
			if (getAPIToken()) {
				throw new UserError(
					"You're already authenticated with Cloudflare, so `--temporary` can't be used. Temporary preview accounts are only for unauthenticated use. Either remove `--temporary` to use your existing account, or log out (and unset CLOUDFLARE_API_TOKEN) first.",
					{
						telemetryMessage: "user temporary account already authenticated",
					}
				);
			}

			const { account: temporaryPreviewAccount, cached } =
				await oauthFlow.activateTemporaryAccount();
			logTemporaryPreviewAccount(
				temporaryAccountLogger,
				temporaryPreviewAccount,
				cached
			);
			return temporaryPreviewAccount.account.id;
		}

		const result = await loginOrRefreshIfRequired(config);
		if (!result.loggedIn) {
			if (
				result.reason === "no-credentials-non-interactive" ||
				result.reason === "token-expired-non-interactive"
			) {
				throw new UserError(
					`In a non-interactive environment, it's necessary to set a CLOUDFLARE_API_TOKEN environment variable for ${cliName} to work. Please go to https://developers.cloudflare.com/fundamentals/api/get-started/create-token/ for instructions on how to create an api token, and assign its value to CLOUDFLARE_API_TOKEN.`,
					{ telemetryMessage: "user auth missing api token non interactive" }
				);
			} else if (result.reason === "token-refresh-unreachable") {
				throw new UserError(NOT_LOGGED_IN_ERROR_BODIES[result.reason], {
					telemetryMessage: "user auth token refresh unreachable",
				});
			} else {
				// didn't login, let's just quit
				throw new UserError("Did not login, quitting...", {
					telemetryMessage: "user login cancelled",
				});
			}
		}

		const accountId = await getOrSelectAccountId(config);
		if (!accountId) {
			throw new UserError("No account id found, quitting...", {
				telemetryMessage: "user auth missing account id",
			});
		}

		return accountId;
	}

	return {
		setProfile,
		getActiveProfile,
		getCredentialStore,
		setTemporaryAllowed,
		getAPIToken,
		requireApiToken,
		login,
		logout,
		loginOrRefreshIfRequired,
		getOAuthTokenFromLocalState,
		getScopes,
		readAuthCredentials,
		writeAuthCredentials,
		getActiveAccountId,
		getOrSelectAccountId,
		getAccountFromCache,
		fetchAllAccounts,
		requireAuth,
	};
}
