// Keep the D1 error copy below in sync with the CLI copy in
// packages/wrangler/src/d1/create.ts.
async function createD1Database(
	complianceConfig: ComplianceConfig,
	accountId: string,
	name: string
) {
	try {
		return await fetchResult<DatabaseCreationResult>(
			complianceConfig,
			`/accounts/${accountId}/d1/database`,
			{
				method: "POST",
				headers: {
					"Content-Type": "application/json",
				},
				body: JSON.stringify({ name }),
			}
		);
	} catch (e) {
		const errorCode = (e as { code: number }).code;

		if (errorCode === 7502) {
			throw new UserError("A database with that name already exists", {
				telemetryMessage: "d1 create database already exists",
			});
		}

		if (errorCode === 7406) {
			throw new UserError(
				dedent`
					You have reached the maximum number of D1 databases for your account.

					On the Workers Free plan? Upgrade to create more:
					https://dash.cloudflare.com/${accountId}/workers/plans

					Already on a paid plan? You can request a higher limit — learn more in the D1 docs:
					https://developers.cloudflare.com/d1/

					Or free up space:
					To list your existing databases, run: wrangler d1 list
					To delete a database, run: wrangler d1 delete <database-name>
				`,
				{ telemetryMessage: "d1 create database limit reached" }
			);
		}

		throw e;
	}
}

async function listDatabases(
	complianceConfig: ComplianceConfig,
	accountId: string,
	limitCalls = false,
	pageSize = 10
): Promise<Array<ConcreteDatabase>> {
	let page = 1;
	const results = [];
	while (results.length % pageSize === 0) {
		const json: Array<ConcreteDatabase> = await fetchResult(
			complianceConfig,
			`/accounts/${accountId}/d1/database`,
			{},
			new URLSearchParams({
				per_page: pageSize.toString(),
				page: page.toString(),
			})
		);
		page++;
		results.push(...json);
		if (limitCalls && page > 3) {
			break;
		}
		if (json.length < pageSize) {
			break;
		}
	}
	return results;
}

