import assert from "node:assert";
import path, { dirname } from "node:path";
import {
	InstanceType,
	resolveImageName,
	SchedulingPolicy,
} from "@cloudflare/containers-shared";
import {
	getDurableObjectClassNameToUseSQLiteMap,
	isDockerfile,
	isDurableObjectContainerApp,
	resolveContainerClassName,
	UserError,
	validateDurableObjectContainerApplications,
} from "@cloudflare/workers-utils";
import { getOrSelectAccountId } from "../user";
import type {
	ApplicationAffinities,
	ApplicationAffinityColocation,
	ContainerNormalizedConfig,
	InstanceTypeOrLimits,
	SharedContainerConfig,
} from "@cloudflare/containers-shared";
import type { ApplicationAffinityHardwareGeneration } from "@cloudflare/containers-shared";
import type {
	Config,
	ContainerApp,
	ContainerObservability,
	Observability,
} from "@cloudflare/workers-utils";

function isContainerObservabilityEnabled(
	observability: ContainerObservability | undefined
): boolean {
	return (
		observability?.logs?.enabled === true || observability?.enabled === true
	);
}

function isRootObservabilityLogsEnabled(
	observability: Observability | undefined
): boolean {
	return (
		observability?.logs?.enabled === true ||
		(observability?.enabled === true && observability?.logs?.enabled !== false)
	);
}

/**
 * Perform type conversion of affinities so that they can be fed to the API.
 */
function convertContainerAffinitiesForApi(
	container: ContainerApp
): ApplicationAffinities | undefined {
	if (container.affinities === undefined) {
		return undefined;
	}

	const affinities: ApplicationAffinities = {
		colocation: container.affinities?.colocation as
			| ApplicationAffinityColocation
			| undefined,
		hardware_generation: container.affinities?.hardware_generation as
			| ApplicationAffinityHardwareGeneration
			| undefined,
	};

	return affinities;
}

/**
 * This normalises config into an intermediate shape for building or pulling.
 * We set defaults here too, because we can assume that if the value is undefined,
 * we want to revert to the default rather than inheriting from the prev deployment
 */
export const getNormalizedContainerOptions = async (
	config: Config,
	args: {
		/** set by args.containersRollout */
		containersRollout?: "gradual" | "immediate" | "none";
		dryRun?: boolean;
	}
): Promise<ContainerNormalizedConfig[]> => {
	if (!config.containers || config.containers.length === 0) {
		return [];
	}

	validateDurableObjectContainerApplications(config);

	const normalizedContainers: ContainerNormalizedConfig[] = [];
	const allDOs = getDurableObjectClassNameToUseSQLiteMap(
		config.migrations,
		config.exports
	);

	for (const container of config.containers) {
		if (isDurableObjectContainerApp(container)) {
			continue;
		}

		assert(container.name, "container name should have been set by validation");
		assert(
			container.image,
			"container image should have been set by validation"
		);

		// A container is linked to its Durable Object either by its own
		// `class_name`, or by the Durable Object's `exports` entry naming it via
		// `container`.
		const className = resolveContainerClassName(container, config.exports);
		if (className === undefined) {
			throw new UserError(
				`The container "${container.name}" is not linked to a Durable Object. Either set "containers.class_name", or reference this container from a Durable Object's \`exports\` entry via its "container" field.`,
				{ telemetryMessage: "container not linked to a durable object" }
			);
		}

		if (
			!allDOs.has(className) &&
			config.durable_objects.bindings.find(
				(doBinding) => doBinding.class_name === className
			) === undefined
		) {
			throw new UserError(
				`The container class_name ${className} does not match any durable object class_name defined in your Wrangler config file. Note that the durable object must be defined in the same script as the container.`,
				{ telemetryMessage: "no DO defined that matches container class_name" }
			);
		}
		const maybeBoundDO = config.durable_objects.bindings.find(
			(durableObject) => durableObject.class_name === className
		);
		if (maybeBoundDO && maybeBoundDO.script_name !== undefined) {
			throw new UserError(
				`The container ${container.name} is referencing the durable object ${className}, which appears to be defined on the ${maybeBoundDO.script_name} Worker instead (via the 'script_name' field). You cannot configure a container on a Durable Object that is defined in another Worker.`,
				{
					telemetryMessage:
						"contaienr class_name refers to an external durable object",
				}
			);
		}

		const rolloutStepPercentageFallback =
			(container.max_instances ?? 0) < 2 ? 100 : [10, 100];

		// tiers will take precedence over tier
		// if unset, wrangler will default to [1, 2]
		// A value of -1 will be treated as "all tiers"
		let tiers: number[] | undefined;
		if (container.constraints?.tiers) {
			tiers = container.constraints.tiers;
			// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, falls back to deprecated `tier` when `tiers` is not set
		} else if (container.constraints?.tier === -1) {
			tiers = undefined;
			// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, falls back to deprecated `tier` when `tiers` is not set
		} else if (container.constraints?.tier) {
			// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, falls back to deprecated `tier` when `tiers` is not set
			tiers = [container.constraints.tier];
		} else {
			tiers = [1, 2];
		}

		let selectedObservabilityLogsEnabled = isRootObservabilityLogsEnabled(
			config.observability
		);

		if (container.observability !== undefined) {
			selectedObservabilityLogsEnabled = isContainerObservabilityEnabled(
				container.observability
			);
		}

		const shared: Omit<SharedContainerConfig, "disk_size" | "instance_type"> = {
			name: container.name,
			class_name: className,
			max_instances: container.max_instances ?? 20,
			scheduling_policy: (container.scheduling_policy ??
				SchedulingPolicy.DEFAULT) as SchedulingPolicy,
			constraints: {
				tiers,
				regions: container.constraints?.regions?.map((region) =>
					region.toUpperCase()
				),
				jurisdiction: container.constraints?.jurisdiction?.toLowerCase(),
				cities: container.constraints?.cities?.map((city) =>
					city.toLowerCase()
				),
			},
			affinities: convertContainerAffinitiesForApi(container),
			rollout_step_percentage:
				args?.containersRollout === "immediate"
					? 100
					: (container.rollout_step_percentage ??
						rolloutStepPercentageFallback),
			rollout_kind:
				args?.containersRollout === "none"
					? "none"
					: (container.rollout_kind ?? "full_auto"),
			rollout_active_grace_period: container.rollout_active_grace_period ?? 0,
			observability: {
				logs_enabled: selectedObservabilityLogsEnabled,
				...(container.observability?.target_instance_percentage !== undefined
					? {
							target_instance_percentage:
								container.observability.target_instance_percentage,
						}
					: {}),
				...(container.observability?.target_instance_count !== undefined
					? {
							target_instance_count:
								container.observability.target_instance_count,
						}
					: {}),
			},
			// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, falls back to deprecated `wrangler_ssh` when `ssh` is not set
			wrangler_ssh: container.ssh ?? container.wrangler_ssh,
			authorized_keys: container.authorized_keys,
			trusted_user_ca_keys: container.trusted_user_ca_keys,
		};

		let instanceTypeOrLimits: InstanceTypeOrLimits;
		const MB = 1000 * 1000;
		if (
			// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, deprecated `configuration` path for custom instance types
			container.configuration?.disk !== undefined ||
			// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, deprecated `configuration` path for custom instance types
			container.configuration?.vcpu !== undefined ||
			// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, deprecated `configuration` path for custom instance types
			container.configuration?.memory_mib !== undefined
		) {
			// deprecated path to set a custom instance type
			// if an individual limit is not set, default to the dev instance type values
			instanceTypeOrLimits = {
				// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, deprecated `configuration` path for custom instance types
				disk_bytes: (container.configuration?.disk?.size_mb ?? 2000) * MB, // defaults to 2GB in bytes
				// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, deprecated `configuration` path for custom instance types
				vcpu: container.configuration?.vcpu ?? 0.0625,
				// eslint-disable-next-line @typescript-eslint/no-deprecated -- kept for backward compatibility, deprecated `configuration` path for custom instance types
				memory_mib: container.configuration?.memory_mib ?? 256,
			};
		} else if (
			typeof container.instance_type === "string" ||
			container.instance_type === undefined
		) {
			instanceTypeOrLimits = {
				instance_type: (container.instance_type ??
					InstanceType.LITE) as InstanceType,
			};
		} else {
			// set a custom instance type
			// any limits that are not set will default to a lite instance type
			instanceTypeOrLimits = {
				disk_bytes: (container.instance_type.disk_mb ?? 2000) * MB,
				vcpu: container.instance_type.vcpu ?? 0.0625,
				memory_mib: container.instance_type.memory_mib ?? 256,
			};
		}

		const maybeDockerfile = isDockerfile(container.image, config.configPath);
		if (maybeDockerfile) {
			// these should have been resolved to absolute paths by the config validation
			assert(
				path.isAbsolute(container.image),
				"Dockerfile path should be absolute"
			);
			const imageBuildContext =
				container.image_build_context ?? dirname(container.image);
			assert(
				path.isAbsolute(imageBuildContext),
				"resolved image_build_context should be defined"
			);
			normalizedContainers.push({
				...shared,
				...instanceTypeOrLimits,
				dockerfile: container.image,
				image_build_context: imageBuildContext,
				image_vars: container.image_vars,
			});
		} else {
			normalizedContainers.push({
				...shared,
				...instanceTypeOrLimits,
				image_uri: args.dryRun
					? container.image
					: resolveImageName(
							await getOrSelectAccountId(config),
							container.image,
							config
						), // if it is not a dockerfile, it must be an image uri or have thrown an error
			});
		}
	}

	return normalizedContainers;
};
