export const kvNamespaceCreateCommand = createCommand({
	metadata: {
		description: "Create a new namespace",
		status: "stable",
		owner: "Product: KV",
	},
	behaviour: { supportTemporary: true },

	args: {
		namespace: {
			describe: "The name of the new namespace",
			type: "string",
			demandOption: true,
		},
		preview: {
			type: "boolean",
			describe: "Interact with a preview namespace",
		},
		jurisdiction: {
			type: "string",
			describe:
				'The jurisdiction where the new namespace will be created (e.g. "us", "eu", "fedramp")',
			requiresArg: true,
		},
		"experimental-mode": {
			alias: "x-mode",
			type: "string",
			describe:
				"The storage mode for the new namespace. Instant mode offers lower-latency reads and faster global updates [private beta].\nCannot be combined with --jurisdiction.",
			choices: ["instant"] as const,
			requiresArg: true,
			conflicts: "jurisdiction",
		},
		...sharedResourceCreationArgs,
	},
	positionalArgs: ["namespace"],
	async handler(args, { sdk }) {
		const config = readConfig(args);
		const environment = args.env ? `${args.env}-` : "";
		const preview = args.preview ? "_preview" : "";
		const title = `${environment}${args.namespace}${preview}`;
		const { jurisdiction, experimentalMode: mode } = args;

		const accountId = await requireAuth(config);
		printResourceLocation("remote");
		// TODO: generate a binding name stripping non alphanumeric chars
		logger.log(
			`🌀 Creating namespace with title "${title}"${
				jurisdiction ? ` (jurisdiction: ${jurisdiction})` : ""
			}${mode ? ` (mode: ${mode})` : ""}`
		);

		let namespaceId: string;
		try {
			const createParams: Cloudflare.KV.Namespaces.NamespaceCreateParams & {
				jurisdiction?: string;
				mode?: string;
			} = {
				account_id: accountId,
				title,
				jurisdiction,
				mode,
			};
			const result = await sdk.kv.namespaces.create(createParams);
			namespaceId = result.id;
		} catch (e) {
			if (
				e instanceof Cloudflare.APIError &&
				e.errors.some((err) => err.code === 10014)
			) {
				throw new UserError(
					dedent`
					A KV namespace with the title "${title}" already exists.

					You can list existing namespaces with their IDs by running:
					  wrangler kv namespace list

					Or choose a different namespace name.
				`,
					{
						telemetryMessage: "kv namespace create namespace already exists",
					}
				);
			}
			throw e;
		}

		metrics.sendMetricsEvent("create kv namespace", {
			sendMetrics: config.send_metrics,
		});

		logger.log("✨ Success!");
		const previewString = args.preview ? "preview_" : "";

		await createdResourceConfig(
			"kv_namespaces",
			(name) => ({
				binding: getValidBindingName(name ?? args.namespace, "KV"),
				[`${previewString}id`]: namespaceId,
			}),
			config.configPath,
			args.env,
			{ ...args, updateConfig: preview ? false : args.updateConfig }
		);
	},
});

export const kvNamespaceListCommand = createCommand({
	metadata: {
		description:
			"Output a list of all KV namespaces associated with your account id",
		status: "stable",
		owner: "Product: KV",
	},

	args: {},

	behaviour: {
		supportTemporary: true,
		printBanner: false,
		printResourceLocation: false,
	},
	async handler(_, { config, sdk }) {
		const accountId = await requireAuth(config);

		const allNamespaces = [];

		for await (const namespace of sdk.kv.namespaces.list({
			account_id: accountId,
			per_page: 1000,
			order: "title",
			direction: "asc",
		})) {
			allNamespaces.push(namespace);
		}

		logger.log(JSON.stringify(allNamespaces, null, "  "));
		metrics.sendMetricsEvent("list kv namespaces", {
			sendMetrics: config.send_metrics,
		});
	},
});

export const kvNamespaceDeleteCommand = createCommand({
	metadata: {
		description: "Delete a given namespace.",
		status: "stable",
		owner: "Product: KV",
	},
	behaviour: { supportTemporary: true },
	positionalArgs: ["namespace"],
	args: {
		namespace: {
			type: "string",
			describe: "The name of the namespace to delete",
		},
		binding: {
			type: "string",
			requiresArg: true,
			describe: "The binding name to the namespace to delete from",
		},
		"namespace-id": {
			type: "string",
			requiresArg: true,
			describe: "The id of the namespace to delete",
		},
		preview: {
			type: "boolean",
			describe: "Interact with a preview namespace",
		},
		"skip-confirmation": {
			type: "boolean",
			description: "Skip confirmation",
			alias: "y",
			default: false,
		},
	},

	validateArgs(args) {
		// Check that exactly one of namespace, binding, or namespace-id is provided
		const providedOptions = [
			args.namespace,
			args.binding,
			args.namespaceId,
		].filter(Boolean);

		if (providedOptions.length === 0) {
			throw new CommandLineArgsError(
				"No KV namespace specified. Provide a namespace name as a positional argument, or use `--binding` or `--namespace-id`.",
				{ telemetryMessage: "kv namespace delete missing namespace selector" }
			);
		}

		if (providedOptions.length > 1) {
			throw new CommandLineArgsError(
				"Only one namespace selector is allowed. Provide exactly one of: a positional namespace name, `--binding`, or `--namespace-id`.",
				{
					telemetryMessage:
						"kv namespace delete conflicting namespace selectors",
				}
			);
		}
	},

	async handler(args) {
		const config = readConfig(args);
		printResourceLocation("remote");
		const accountId = await requireAuth(config);

		let namespaceId: string;
		let displayName: string;
		try {
			({ namespaceId, displayName } = await getKVNamespaceId(
				args,
				config,
				false
			));
		} catch (e) {
			throw new CommandLineArgsError(
				"Not able to delete namespace.\n" + ((e as Error).message ?? e),
				{ telemetryMessage: "kv namespace delete namespace resolution failed" }
			);
		}

		logger.log(
			`About to delete ${chalk.bold("remote")} KV namespace ${displayName}.\n` +
				`This action is irreversible and will permanently delete all data in the KV namespace.\n`
		);
		if (!args.skipConfirmation) {
			const response = await confirm(`Ok to proceed?`);
			if (!response) {
				logger.log(`Not deleting.`);
				return;
			}
		}

		logger.log(`Deleting KV namespace ${displayName}.`);
		await deleteKVNamespace(config, accountId, namespaceId);
		logger.log(`Deleted KV namespace ${displayName}.`);
		metrics.sendMetricsEvent("delete kv namespace", {
			sendMetrics: config.send_metrics,
		});

		// TODO: recommend they remove it from wrangler.toml

		// test-mf wrangler kv:namespace delete --namespace-id 2a7d3d8b23fc4159b5afa489d6cfd388
		// Are you sure you want to delete namespace 2a7d3d8b23fc4159b5afa489d6cfd388? [y/n]
		// n
		// 💁  Not deleting namespace 2a7d3d8b23fc4159b5afa489d6cfd388
		// ➜  test-mf wrangler kv:namespace delete --namespace-id 2a7d3d8b23fc4159b5afa489d6cfd388
		// Are you sure you want to delete namespace 2a7d3d8b23fc4159b5afa489d6cfd388? [y/n]
		// y
		// 🌀  Deleting namespace name: "my kv store" (id: "2a7d3d8b23fc4159b5afa489d6cfd388")
		// ✨  Success
		// ⚠️  Make sure to remove this "kv-namespace" entry from your configuration file!
		// ➜  test-mf

		// TODO: do it automatically

		// TODO: delete the preview namespace as well?
	},
});

export const kvNamespaceRenameCommand = createCommand({
	metadata: {
		description: "Rename a KV namespace",
		status: "stable",
		owner: "Product: KV",
	},
	behaviour: { supportTemporary: true },
	positionalArgs: ["old-name"],
	args: {
		"old-name": {
			type: "string",
			describe: "The current name of the namespace to rename",
		},
		"namespace-id": {
			type: "string",
			describe: "The id of the namespace to rename",
		},
		"new-name": {
			type: "string",
			describe: "The new name for the namespace",
			demandOption: true,
		},
	},

	validateArgs(args) {
		// Check if both name and namespace-id are provided
		if (args.oldName && args.namespaceId) {
			throw new CommandLineArgsError(
				"Cannot specify both a positional namespace name and `--namespace-id`. Use one or the other to identify the namespace to rename.",
				{
					telemetryMessage:
						"kv namespace rename conflicting namespace selectors",
				}
			);
		}

		// Require either old-name or namespace-id
		if (!args.namespaceId && !args.oldName) {
			throw new CommandLineArgsError(
				"No KV namespace specified. Provide the current namespace name as a positional argument, or use `--namespace-id` to identify the namespace to rename.",
				{ telemetryMessage: "kv namespace rename missing namespace selector" }
			);
		}

		// Validate new-name length (API limit is 512 characters)
		if (args.newName && args.newName.length > 512) {
			throw new CommandLineArgsError(
				`The new namespace name exceeds the 512-character limit (got ${args.newName.length} characters). Provide a shorter name with \`--new-name\`.`,
				{ telemetryMessage: "kv namespace rename new name too long" }
			);
		}
	},

	async handler(args) {
		const config = readConfig(args);
		printResourceLocation("remote");
		const accountId = await requireAuth(config);

		let namespaceId = args.namespaceId;

		// If no namespace ID provided, find it by current name
		if (!namespaceId && args.oldName) {
			const namespaces = await listKVNamespaces(config, accountId);
			const namespace = namespaces.find((ns) => ns.title === args.oldName);

			if (!namespace) {
				throw new UserError(
					`No KV namespace named "${args.oldName}" was found in your account. Use \`--namespace-id\` to identify the namespace by ID, or run \`wrangler kv namespace list\` to see all available namespaces.`,
					{ telemetryMessage: "kv namespace rename namespace not found" }
				);
			}
			namespaceId = namespace.id;
		}

		assert(namespaceId, "namespaceId should be defined");
		logger.log(`Renaming KV namespace ${namespaceId} to "${args.newName}".`);
		const updatedNamespace = await updateKVNamespace(
			config,
			accountId,
			namespaceId,
			args.newName
		);
		logger.log(
			`✨ Successfully renamed namespace to "${updatedNamespace.title}"`
		);
	},
});

/**
 * Common args shared between `kv key put` and `kv bulk put` commands
 */
const putCommonArgs = {
	binding: {
		type: "string",
		requiresArg: true,
		describe: "The binding name to the namespace to write to",
	},
	"namespace-id": {
		type: "string",
		requiresArg: true,
		describe: "The id of the namespace to write to",
	},
	preview: {
		type: "boolean",
		describe: "Interact with a preview namespace",
	},
	ttl: {
		type: "number",
		describe: "Time for which the entries should be visible",
	},
	expiration: {
		type: "number",
		describe: "Time since the UNIX epoch after which the entry expires",
	},
	metadata: {
		type: "string",
		describe: "Arbitrary JSON that is associated with a key",
		coerce: (jsonStr: string): KeyValue["metadata"] => {
			let parsed: unknown;
			try {
				parsed = JSON.parse(jsonStr);
			} catch {
				throw new CommandLineArgsError(
					`--metadata must be valid JSON. Received: ${jsonStr}`,
					{ telemetryMessage: "kv key put --metadata not valid JSON" }
				);
			}
			if (
				parsed === null ||
				Array.isArray(parsed) ||
				typeof parsed !== "object"
			) {
				throw new CommandLineArgsError(
					`--metadata must be a JSON object. Received: ${jsonStr}`,
					{ telemetryMessage: "kv key put --metadata not a JSON object" }
				);
			}
			return parsed as KeyValue["metadata"];
		},
	},
	local: {
		type: "boolean",
		describe: "Interact with local storage",
	},
	remote: {
		type: "boolean",
		describe: "Interact with remote storage",
		conflicts: "local",
	},
	"persist-to": {
		type: "string",
		describe: "Directory for local persistence",
	},
} as const;

export const kvKeyPutCommand = createCommand({
	metadata: {
		description: "Write a single key/value pair to the given namespace",
		status: "stable",
		owner: "Product: KV",
	},
	behaviour: {
		supportTemporary: true,
		printResourceLocation: true,
	},
	positionalArgs: ["key", "value"],
	args: {
		key: {
			type: "string",
			describe: "The key to write to",
			demandOption: true,
		},
		value: {
			type: "string",
			describe: "The value to write",
		},
		path: {
			type: "string",
			requiresArg: true,
			describe: "Read value from the file at a given path",
		},
		...putCommonArgs,
	},
	validateArgs(args, def) {
		demandOneOfOption(["binding", "namespace-id"])(args);
		demandOneOfOption(["value", "path"], def)(args);
	},

	async handler({ key, ttl, expiration, metadata, ...args }) {
		const localMode = isLocal(args);
		const config = readConfig(args);
		const { namespaceId, displayName } = await getKVNamespaceId(
			args,
			config,
			localMode
		);
		// One of `args.path` and `args.value` must be defined
		const value = args.path ? readFileSyncToBuffer(args.path) : args.value;
		assert(value);

		const metadataLog = metadata
			? ` with metadata "${JSON.stringify(metadata)}"`
			: "";

		if (args.path) {
			logger.log(
				`Writing the contents of ${args.path} to the key "${key}" on namespace ${displayName}${metadataLog}.`
			);
		} else {
			logger.log(
				`Writing the value "${value}" to key "${key}" on namespace ${displayName}${metadataLog}.`
			);
		}

		let metricEvent: EventNames;
		if (localMode) {
			await usingLocalNamespace(
				args.persistTo,
				config,
				namespaceId,
				(namespace) =>
					namespace.put(key, new Blob([value]).stream(), {
						expiration,
						expirationTtl: ttl,
						metadata,
					})
			);

			metricEvent = "write kv key-value (local)";
		} else {
			const accountId = await requireAuth(config);

			await putKVKeyValue(config, accountId, namespaceId, {
				key,
				value,
				expiration,
				expiration_ttl: ttl,
				metadata: metadata as KeyValue["metadata"],
			});

			metricEvent = "write kv key-value";
		}

		metrics.sendMetricsEvent(metricEvent, {
			sendMetrics: config.send_metrics,
		});
	},
});

export const kvKeyListCommand = createCommand({
	metadata: {
		description: "Output a list of all keys in a given namespace",
		status: "stable",
		owner: "Product: KV",
	},
	behaviour: {
		supportTemporary: true,
		// implicitly expects to output JSON only
		printResourceLocation: false,
		printBanner: false,
	},

	args: {
		binding: {
			type: "string",
			requiresArg: true,
			describe: "The binding name to the namespace to list",
		},
		"namespace-id": {
			type: "string",
			requiresArg: true,
			describe: "The id of the namespace to list",
		},
		preview: {
			type: "boolean",
			// In the case of listing keys we will default to non-preview mode
			default: false,
			describe: "Interact with a preview namespace",
		},
		prefix: {
			type: "string",
			requiresArg: true,
			describe: "A prefix to filter listed keys",
		},
		local: {
			type: "boolean",
			describe: "Interact with local storage",
		},
		remote: {
			type: "boolean",
			describe: "Interact with remote storage",
			conflicts: "local",
		},
		"persist-to": {
			type: "string",
			describe: "Directory for local persistence",
		},
	},
	validateArgs(args) {
		demandOneOfOption(["binding", "namespace-id"])(args);
	},

	async handler({ prefix, ...args }) {
		const localMode = isLocal(args);
		// TODO: support for limit+cursor (pagination)
		const config = readConfig(args);
		const { namespaceId } = await getKVNamespaceId(args, config, localMode);

		let result: NamespaceKeyInfo[];
		let metricEvent: EventNames;
		if (localMode) {
			const listResult = await usingLocalNamespace(
				args.persistTo,
				config,
				namespaceId,
				(namespace) => namespace.list({ prefix })
			);
			result = listResult.keys as NamespaceKeyInfo[];

			metricEvent = "list kv keys (local)";
		} else {
			const accountId = await requireAuth(config);

			result = await listKVNamespaceKeys(
				config,
				accountId,
				namespaceId,
				prefix
			);
			metricEvent = "list kv keys";
		}

		logger.log(JSON.stringify(result, undefined, 2));
		metrics.sendMetricsEvent(metricEvent, {
			sendMetrics: config.send_metrics,
		});
	},
});

